<script setup>
import {ref,onMounted,computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {get,api} from '../api/client';import EvidenceViewer from '../components/EvidenceViewer.vue';const route=useRoute(),router=useRouter();const error=ref(''),busy=ref(false),rev=ref(null),evidence=ref([]),items=ref([]),suppliers=ref([]),products=ref([]),itemLabels=ref({}),form=ref({kind:'set_availability',target:'',status:'temporarily_unavailable',amount:'',from:new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Seoul'}),to:'',reason:'',justification:'',supersedes:'',name:'',spec:'',supplier:'',code:'',sales_unit:'kg',tax:'unknown'}),chosen=ref([]);const f=computed(()=>form.value);onMounted(async()=>{try{if(!route.query.revision)throw new Error('문서 상세에서 변경안 작성을 시작하세요.');[rev.value,{items:evidence.value},{items:items.value},{items:suppliers.value},{items:products.value}]=await Promise.all([get('/document-revisions/'+route.query.revision),get('/document-revisions/'+route.query.revision+'/evidence'),get('/supplier-items?limit=100'),get('/suppliers?limit=100'),get('/products?limit=100')]);const details=await Promise.all(products.value.map(p=>get('/products/'+p.id)));for(const p of details)for(const v of p.variants)for(const i of items.value.filter(x=>x.variant_id===v.id))itemLabels.value[i.id]=[p.name,v.spec_original,suppliers.value.find(s=>s.id===i.supplier_id)?.name,i.supplier_code].filter(Boolean).join(' · ');chosen.value=evidence.value.slice(0,1).map(e=>e.id)}catch(e){error.value=e.message}});async function submit(){busy.value=true;error.value='';try{if(!chosen.value.length)throw new Error('먼저 문서를 분석해 추출 근거를 생성하고, 근거를 선택하세요.');if(!f.value.justification.trim())throw new Error('검토자 판단 사유를 입력하세요.');const period={effective_from:f.value.from,effective_to:f.value.to||null},reason={original_text:f.value.reason||null,summary:f.value.reason||null,code:null},value={amount:f.value.amount,currency:'KRW',quantity:'1',unit:f.value.sales_unit,tax:f.value.tax,price_kind:'regular',condition_key:'public'};let ops=[];if(f.value.kind==='new'){ops=[{kind:'create_product',local_ref:'new_product',name:f.value.name,manufacturer_id:null,brand_id:null},{kind:'create_variant',local_ref:'new_variant',product_ref:{local_ref:'new_product'},spec_original:f.value.spec,spec_normalized:f.value.spec,barcode:null},{kind:'create_supplier_item',local_ref:'new_item',variant_ref:{local_ref:'new_variant'},supplier_id:f.value.supplier,supplier_code:f.value.code||null,sales_unit:f.value.sales_unit},{kind:'set_price',supplier_item_ref:{local_ref:'new_item'},value,period,reason,supersedes_fact_id:null}]}else{const op={kind:f.value.kind,supplier_item_ref:{id:f.value.target},period,reason,supersedes_fact_id:f.value.supersedes||null};if(f.value.kind==='set_price')op.value=value;else op.status=f.value.status;ops=[op]}const changes=ops.map(operation=>({id:crypto.randomUUID(),operation,field_evidence:Object.keys(operation).filter(k=>!['kind','local_ref','supersedes_fact_id','manufacturer_id','brand_id','barcode','supplier_code'].includes(k)).map(k=>({field_path:'/'+k,evidence_ids:chosen.value,origin:'reviewer',reviewer_justification:f.value.justification}))}));const {data:p}=await api('/proposals',{method:'POST',body:{title:rev.value.title+' · 수동 검토',source_document_revision_ids:[rev.value.id],changes}});router.push('/reviews/'+p.summary.id)}catch(e){error.value=e.message}finally{busy.value=false}}
</script><template><div class="page-heading"><div><div class="eyebrow">REVIEWER DRAFT</div><h1>변경안 직접 작성</h1><p class="muted">추출 근거를 연결하고, 정확한 상품과 변경 내용을 지정하세요.</p></div><button class="secondary" @click="$router.back()">뒤로</button></div><p v-if="error" class="error">{{error}}</p><div class="review-grid"><form class="panel manual-form" @submit.prevent="submit"><h2>{{rev?.title||'문서 확인'}}</h2><label>변경 종류<select v-model="form.kind"><option value="set_availability">공급 상태</option><option value="set_price">기존 품목 단가</option><option value="new">신규 식품·규격·공급 품목·단가 등록</option></select></label><template v-if="form.kind==='new'"><label>식품명<input v-model="form.name" required></label><label>규격<input v-model="form.spec" required placeholder="예: 50g × 20개"></label><label>공급 업체<select v-model="form.supplier" required><option value="">업체 선택</option><option v-for="s in suppliers" :value="s.id">{{s.name}}</option></select></label><label>공급처 품목코드<input v-model="form.code"></label></template><label v-else>대상 공급 품목<select v-model="form.target" required><option value="">정확한 품목을 선택하세요</option><option v-for="i in items" :value="i.id">{{itemLabels[i.id]||i.supplier_code||'품목 정보 확인 필요'}}</option></select></label><label v-if="form.kind==='set_availability'">공급 상태<select v-model="form.status"><option value="temporarily_unavailable">공급 일시중단</option><option value="available">공급 재개</option><option value="supply_ended">공급 종료</option><option value="unknown">미확인</option></select></label><template v-else><label>단가 (원)<input v-model="form.amount" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,4})?" required></label><div class="row"><label>1단위 기준<select v-model="form.sales_unit"><option v-for="u in ['g','kg','ml','l','ea','bag','box','pack']">{{u}}</option></select></label><label>세금<select v-model="form.tax"><option value="unknown">미확인</option><option value="included">포함</option><option value="excluded">별도</option></select></label></div></template><div class="row"><label>적용 시작일<input type="date" v-model="form.from" required></label><label>종료일 (해당 날짜 제외)<input type="date" v-model="form.to"></label></div><label>원문에 기재된 사유<input v-model="form.reason" placeholder="기재된 사유가 없다면 비워 두세요"></label><label v-if="form.kind!=='new'">정정 대상 사실 ID (기간이 겹칠 때)<input v-model="form.supersedes" placeholder="이력 상세의 after.id 또는 단가표 fact ID"></label><label>검토자 판단 사유<textarea v-model="form.justification" rows="3" required placeholder="대상 상품과 적용일을 어떻게 확인했나요?"></textarea></label><label>연결할 추출 근거<select v-model="chosen" multiple size="4" required><option v-for="e in evidence" :value="e.id">{{e.quote.slice(0,90)}}</option></select></label><div v-if="!evidence.length" class="warning">아직 추출 근거가 없습니다. 문서 상세에서 먼저 ‘변경안 분석’을 실행하세요. 규칙 분석에 실패해도 텍스트 추출이 완료되면 근거를 사용할 수 있습니다.</div><button class="primary" :disabled="busy||!chosen.length">초안 생성·검증 →</button></form><EvidenceViewer :ids="chosen"/></div></template>
